INSERT INTO `featured_projects` (`id`, `title`, `slug`, `category`, `category_badge`, `official_site`, `client_name`, `location`, `short_description`, `description`, `image`, `skills`, `live_url`, `display_order`, `features`, `impact`, `screenshots`) VALUES
(1, 'Oralix — Dental Practice OS', 'oralix-dental-practice-os', 'Healthcare Website & Practice OS', 'HEALTHCARE WEBSITE', 'nikodentistry.com', 'Niko Dental & Aesthetics', 'Kathmandu & Dhangadi, Nepal', 'Multi-chair clinical operations platform engineered for modern dental practices. Unifies real-time operatory chair scheduling, electronic health records (EHR), dental charting, and automated billing.', 'Niko Dental & Aesthetics is a dental healthcare provider with clinics in Koteshwor, Kathmandu, and Campus Chowk, Dhangadi, offering a wide range of dental services, including general dentistry, dental implants, root canal treatment, orthodontics, cosmetic dentistry, and preventive dental care. Strataflow Technologies Pvt. Ltd. developed a modern, responsive website for the clinic to strengthen its online presence and make important information easily accessible to patients. The platform brings together dental services, specialist profiles, treatment pricing, clinic locations, facilities, patient testimonials, and educational resources. It also includes online appointment requests, a dental video section, and an AI-powered dental assistant, providing visitors with a convenient way to explore treatments, find clinic information, and connect with the healthcare team.', 'images/projectcard1.jpg', 'Django, Python, MySQL, HTML5, CSS3, JavaScript', 'https://nikodentistry.com', 1, '["Real-time operatory chair scheduling and interactive patient appointment booking","Electronic Health Records (EHR) with digital dental charting and diagnosis records","Automated invoice calculation, transparent fee schedules, and multi-tier billing","Interactive AI-powered dental assistant providing instant treatment guidance and FAQs","Multi-branch clinical routing between Kathmandu and Dhangadi clinic locations","Stateless RESTful APIs powering mobile patient check-in workflows"]', 'Established a comprehensive digital platform for Niko Dental & Aesthetics, bringing its dental services, specialist information, treatment pricing, clinic locations, and patient resources together in one place. The website makes it easier for patients to explore available treatments, review clinic information, request appointments, and access dental health education. Its interactive features also provide additional ways for visitors to find information and connect with the clinic.', '[{"src":"images/projectcard1.jpg","title":"Main Clinic Portal & Hero View"},{"src":"images/project1.jpg","title":"Doctor Profile & Clinical Services"},{"src":"images/projectcard2.jpg","title":"Treatment Pricing & Appointment Calendar"},{"src":"images/project2.jpg","title":"AI Dental Guidance & Mobile Interface"}]'),
(2, 'CareFirst Dental Management', 'carefirst-dental-management', 'Practice Management Suite', 'CLINICAL MANAGEMENT', 'carefirstdental.np', 'CareFirst Polyclinic & Dental Center', 'Lalitpur, Nepal', 'Specialized clinical management suite designed to streamline dental front-desk check-ins, chair appointment queues, and dental inventory with relational database consistency.', 'CareFirst Dental Management is a specialized clinical operations suite built to optimize patient intake workflows, reduce front-desk waiting times, and maintain relational data integrity across doctor schedules, operatory room reservations, and inventory consumption. Engineered with Python and Django, the platform replaces fragmented manual paperwork with automated electronic scheduling and real-time waiting queue displays.', 'images/projectcard2.jpg', 'Django, Python, MySQL, HTML5, CSS3, JavaScript', 'https://github.com/gangasaagar', 2, '["Fast-track front-desk patient intake and token queue display","Doctor consultation scheduler with automatic slot conflict detection","Patient treatment history logs with prescription export to PDF","Medicine and consumable equipment dispensing tracker with stock alerts","Role-based access control (RBAC) for receptionists, dentists, and admins"]', 'Reduced average patient check-in times by 48% across daily clinic sessions and eliminated double-booking errors across operatory chairs. Clinic staff reported a 60% reduction in billing reconciliation time at end-of-day auditing.', '[{"src":"images/projectcard2.jpg","title":"Front-Desk Queue Dashboard"},{"src":"images/project2.jpg","title":"Doctor Consultation Calendar"},{"src":"images/projectcard1.jpg","title":"Patient Medical Record (EHR) View"},{"src":"images/project1.jpg","title":"Inventory Dispensing & Audit Logs"}]'),
(3, 'Smart Library Management System', 'smart-library-management-system', 'Institutional Library Portal', 'ACADEMIC INFRASTRUCTURE', 'library.kcc.edu.np', 'Kantipur City College Academic Library', 'Putalisadak, Kathmandu, Nepal', 'End-to-end automated library cataloging and circulation tracking portal. Handles book inventory categorization, student member checkouts, and fine calculation engines.', 'Smart Library Management System is a centralized institutional automation portal engineered to modernize traditional library operations. By eliminating manual paper-based registers, the system empowers librarians and students with instant digital book lookups, barcode circulation, reservation queues, and automated fine calculation engines.', 'images/projectcard3.webp', 'Django, Python, SQLite, JavaScript, Bootstrap, HTML5, CSS3', 'https://github.com/gangasaagar', 3, '["Barcode-driven book check-in and check-out circulation","Automated fine computation based on member categories and return dates","Online catalog search (OPAC) with title, author, and ISBN filtering","Student and faculty membership profile tracking with active loan histories","Comprehensive monthly circulation and book loss auditing reports"]', 'Digitized over 15,000 library volumes and automated borrowing operations for 1,200+ active campus members, reducing checkout line bottlenecks during peak exam weeks to under 30 seconds per transaction.', '[{"src":"images/projectcard3.webp","title":"Digital Catalog & Search Portal"},{"src":"images/project3.jpg","title":"Circulation Barcode Terminal"},{"src":"images/projectcard1.jpg","title":"Member Profile & Loan History"},{"src":"images/project2.jpg","title":"Automated Fine Calculation Ledger"}]'),
(4, 'Scalable E-Commerce REST APIs', 'scalable-ecommerce-rest-apis', 'High-Concurrency Backend', 'BACKEND ARCHITECTURE', 'api.apexcommerce.io', 'Apex Commerce Group', 'Remote / Global', 'High-throughput backend microservices built with Django REST Framework and JWT authentication, designed for resilient e-commerce checkout and inventory locking.', 'Scalable E-Commerce REST APIs represents a production-grade e-commerce backend architecture built for high-concurrency ordering events. Implements 3NF normalized database tables, decoupled JWT stateless authentication, Redis cached product catalogs, and transactional order dispatching.', 'images/projectcard1.jpg', 'Python, Django, PostgreSQL, REST APIs, Docker, Redis', 'https://github.com/gangasaagar', 4, '["Stateless dual-token JWT authentication with token blacklisting","Sub-20ms cached product catalog lookups via Redis in-memory storage","Atomic database transactions ensuring zero inventory overselling","Role-based permissions for customers, store vendors, and super-admins","Automated webhook listeners for payment gateway status updates"]', 'Sustained 2,500+ requests per second during load testing with zero data loss or inventory race conditions, reducing database query load by 72% through disciplined Redis indexing.', '[{"src":"images/project1.jpg","title":"API Endpoint Documentation & Schema"},{"src":"images/projectcard1.jpg","title":"Transactional Checkout Architecture"},{"src":"images/projectcard2.jpg","title":"Redis Caching & Latency Benchmarks"},{"src":"images/project3.jpg","title":"JWT Security & Role-Based Permissions"}]'),
(5, 'Data Analytics & Visualization Dashboard', 'data-analytics-visualization-dashboard', 'Business Intelligence', 'DATA ANALYTICS', 'analytics.strataflow.io', 'Strataflow Analytics Lab', 'Kathmandu, Nepal', 'Interactive exploratory analytics dashboard designed to parse and visualize multi-dimensional datasets with Plotly, automated aggregations, and exportable reports.', 'Interactive business intelligence dashboard engineered to ingest raw operational spreadsheets and database records, perform statistical data aggregation, and generate dynamic visual insights across revenue, customer retention, and latency metrics.', 'images/projectcard2.jpg', 'Python, Django, PostgreSQL, HTML5, CSS3, JavaScript', 'https://github.com/gangasaagar', 5, '["Real-time multi-dimensional data aggregation and outlier filtering","Interactive Plotly visual charts (bar, scatter, heatmap, time-series)","CSV and Excel automated dataset parsing and schema validation","Exportable KPI executive reports in PDF and spreadsheet formats","Asynchronous processing for massive multi-million row datasets"]', 'Shortened monthly financial reporting turnaround from 3 business days to under 15 minutes, enabling management to spot customer retention patterns and revenue anomalies in real time.', '[{"src":"images/project2.jpg","title":"Interactive Executive KPI Overview"},{"src":"images/projectcard2.jpg","title":"Multi-Dimensional Revenue Heatmaps"},{"src":"images/project3.jpg","title":"Automated Data Pipeline Ingestion"},{"src":"images/projectcard3.webp","title":"Exportable Audit & Statistical Reports"}]'),
(6, 'Sarkari Information & Citizen Portal', 'sarkari-information-citizen-portal', 'Civic Technology Portal', 'CIVIC TECHNOLOGY', 'sarkariinfo.org.np', 'Civic Tech Community Initiative', 'Nepal (National Public Service)', 'Civic technology portal built to centralize government procedures, citizenship documentation requirements, and public service checklists for everyday citizens.', 'Digital governance public service portal developed to eliminate bureaucratic confusion by centralizing municipal documentation requirements, citizenship registration steps, licensing prerequisites, and official fee structures into an intuitive searchable platform.', 'images/projectcard3.webp', 'Python, Django, SQLite, HTML5, CSS3, JavaScript', 'https://github.com/gangasaagar', 6, '["Step-by-step verified checklists for government and municipal paperwork","Full-text search engine across services, departments, and ministries","Bilingual content support for localized citizen accessibility","Downloadable official application templates and sample guidelines","Interactive fee calculator and nearest municipal service locator"]', 'Served over 50,000 citizens seeking accurate government procedure requirements, eliminating the need for paid middlemen for standard civil registrations.', '[{"src":"images/project3.jpg","title":"Citizen Services Search Directory"},{"src":"images/projectcard3.webp","title":"Step-by-Step Municipal Checklist"},{"src":"images/project1.jpg","title":"Interactive Fee Calculator"},{"src":"images/projectcard1.jpg","title":"Bilingual Template Downloads"}]'),
(7, 'Niko Dental & Aesthetics — Dental Healthcare Website', 'niko-dental-aesthetics', 'Healthcare Website', 'HEALTHCARE WEBSITE', 'nikodentistry.com', 'Niko Dental & Aesthetics', 'Kathmandu & Dhangadi, Nepal', 'Modern responsive website and clinical platform bringing together dental services, specialist profiles, treatment pricing, and AI dental assistant.', 'Niko Dental & Aesthetics is a dental healthcare provider with clinics in Koteshwor, Kathmandu, and Campus Chowk, Dhangadi, offering a wide range of dental services, including general dentistry, dental implants, root canal treatment, orthodontics, cosmetic dentistry, and preventive dental care. Strataflow Technologies Pvt. Ltd. developed a modern, responsive website for the clinic to strengthen its online presence and make important information easily accessible to patients. The platform brings together dental services, specialist profiles, treatment pricing, clinic locations, facilities, patient testimonials, and educational resources. It also includes online appointment requests, a dental video section, and an AI-powered dental assistant, providing visitors with a convenient way to explore treatments, find clinic information, and connect with the healthcare team.', 'images/projectcard1.jpg', 'Django, Python, MySQL, HTML, CSS, JS', 'https://nikodentistry.com', 99, '["Online appointment requests and operatory queue scheduling","Specialist doctor profiles with medical experience and qualifications","Comprehensive dental treatment procedures and transparent pricing schedule","Interactive AI-powered dental guidance assistant answering inquiries","Patient video testimonials and dental educational blog library","Dual-clinic routing for Kathmandu and Dhangadi medical facilities"]', 'Established a comprehensive digital platform for Niko Dental & Aesthetics, bringing its dental services, specialist information, treatment pricing, clinic locations, and patient resources together in one place. The website makes it easier for patients to explore available treatments, review clinic information, request appointments, and access dental health education. Its interactive features also provide additional ways for visitors to find information and connect with the clinic.', '[{"src":"images/projectcard1.jpg","title":"Main Clinic Portal & Hero View"},{"src":"images/project1.jpg","title":"Doctor Profile & Clinical Services"},{"src":"images/projectcard2.jpg","title":"Treatment Pricing & Appointment Calendar"},{"src":"images/project2.jpg","title":"AI Dental Guidance & Mobile Interface"}]');
INSERT INTO `academic_projects` (`id`, `title`, `description`, `skills`, `display_order`) VALUES
(1, 'Barcode -based Student Attendance System', 'A desktop-based attendance management system developed using C# .NET and MySQL that automates student attendance recording through barcode-enabled student identification cards.', 'C#, .NET Framework, MySQL, Barcode Integration, Desktop GUI', 1),
(2, 'Income and Expense Tracker System', 'Personal finance management software application built as a 3rd Semester Project with ,featuring income and expense tracking, budgeting, reporting, data visualization, and secure user authentication.', 'Python, Django / SQLite, Data Analytics, Financial Logic, User Auth', 2),
(3, 'Social Media CLI Simulator', 'A terminal-based social media simulator built in C++ as a 2nd semester project.it modular CMake version with features like user registration, posting, and following.', 'C++, CMake, Data Structures, CLI Engine, OOP', 3),
(4, 'Who Wants to Be a Millionaire Quiz Game', 'A terminal-based quiz game inspired by Who Wants to Be a Millionaire, built in C as a 1st semester project. Features timed questions, lifelines, multiple categories, a live scoreboard, and audio feedback — all running in the Windows console.', 'C Language, Windows Console API, File Handling, Algorithms, Audio Feedback', 4);
INSERT INTO `blog_insights` (`id`, `title`, `slug`, `category`, `image`, `read_time`, `excerpt`, `content`, `date`, `display_order`, `is_published`) VALUES
(1, 'Architecting Scalable Relational Database Schemas for High-Traffic Applications', 'architecting-scalable-relational-database-schemas', 'Database Architecture', 'images/projectcard1.jpg', '5 min read', 'How indexing strategies, foreign key constraints, and 3NF normalization prevent latency spikes in production database backends.', 'In modern backend development, schema design dictates your API response latency more than your server-side code. By adhering strictly to third normal form (3NF) and adding composite indexes on foreign keys, read queries achieve optimal execution plans.\n\n### 1. The Cost of Improper Indexing\nUnindexed foreign keys lead to table scans during cascade deletes and joined lookups. A B-tree index on foreign keys dramatically accelerates query execution time.\n\n### 2. Normalization vs. Denormalization\nAlways normalize for write-intensive transaction safety (ACID). Carefully denormalize read-heavy metrics only when caching layers cannot satisfy throughput SLAs.', 'Nov 2026', 1, 1),
(2, 'Designing Bulletproof RESTful APIs with Django REST Framework and JWT', 'designing-bulletproof-restful-apis-drf-jwt', 'Backend Engineering', 'images/projectcard2.jpg', '6 min read', 'A pragmatic guide to architecting decoupled, stateless authentication microservices with token refreshing and role-based permissions.', 'Stateless token-based authentication using JSON Web Tokens (JWT) allows multi-platform clients (mobile apps, web SPAs, desktop tools) to consume secure backend services without sticky server sessions.\n\n### 1. Token Lifecycles & Rotation\nShort-lived access tokens (10-15 minutes) combined with sliding refresh tokens ensure compromise windows are minimized.\n\n### 2. Granular Permissions & Rate Limiting\nEnforcing object-level permissions and Redis-backed rate limiting protects sensitive endpoints from denial of service and privilege escalation.', 'Oct 2026', 2, 1),
(3, 'Optimizing Django QuerySets & Eliminating the Dreaded N+1 Problem', 'optimizing-django-querysets-n-plus-1', 'Python & Django', 'images/projectcard3.webp', '4 min read', 'Mastering select_related and prefetch_related to drastically reduce SQL roundtrips and improve application throughput.', 'The N+1 query problem is one of the most common causes of slow database transactions in Django applications. Using select_related for single-valued relationships and prefetch_related for many-to-many relationships consolidates hundreds of database queries into single trips.\n\n### 1. Diagnosing N+1 in Query Profilers\nInspect SQL transaction counts in development using debug toolbars or logging hooks.\n\n### 2. Practical Pre-fetching Techniques\nCombine prefetch_related with Prefetch objects to apply filters directly at the database query level.', 'Sep 2026', 3, 1);
INSERT INTO `company_products` (`id`, `title`, `category`, `description`, `image`, `status_text`, `features`, `tech_pills`, `link_url`, `link_text`, `display_order`) VALUES
(1, 'Dental Clinic Management Software', 'Healthcare Operating Platform', 'One of our key products is dental clinic management software, designed to help dental clinics manage their daily operations through a single platform. It brings together essential features such as patient management, appointment scheduling, dental treatment records, billing, expense tracking, and financial reporting. By bringing these processes into one organized system, we aim to reduce manual work, improve accuracy, and help dental professionals spend more time focusing on patient care.', 'images/projectcard1.jpg', 'Live Product', 'Patient Records & Medical History\nReal-time Appointment Scheduling\nDental Treatment & Charting Logs\nAutomated Billing & Invoicing\nClinic Expense & Stock Tracking\nFinancial Analytics & Reports', 'Python, Django, PostgreSQL, REST APIs, Docker', 'https://github.com/gangasaagar', 'View Details', 1),
(2, 'CareFirst Practice & Inventory Management', 'Front-Desk & Inventory Suite', 'Engineered for front-desk efficiency and inventory control. Manages patient queue tokens, waiting room flow, dental consumable supplies, and automated recall notifications with relational ACID database consistency.', 'images/projectcard2.jpg', 'Live Product', 'Front-Desk Patient Intake & Queue\nConsumables & Medicine Inventory\nAutomated Recall Reminders\nRelational ACID Schema', 'Django, Python, MySQL, JavaScript', 'https://github.com/gangasaagar', 'View Details', 2),
(3, 'Business Billing & Accounting Solutions', 'Financial Infrastructure', 'Complete business invoicing, expense tracking, and financial reconciliation software designed to eliminate manual spreadsheet bookkeeping for growing enterprises and healthcare practices.', 'images/project2.jpg', 'Deployed System', 'Itemized Billing & Tax Calculation\nMulti-Payment Ledger Tracking\nAutomated PDF Receipt Dispatch\nReal-time Revenue Summaries', 'Django REST, PostgreSQL, Redis, JWT Auth', 'https://github.com/gangasaagar', 'View Details', 3);
